import React from 'react';

const Hero = () => {
    return (
        <div className="hero">
            <h1>Recordar para defender la democracia</h1>
            <p>
                Campaña educativa sobre la dictadura de los hermanos Tinoco en Costa Rica.
            </p>
            <p>
                Este proyecto tiene como propósito difundir de manera clara, accesible e innovadora la relevancia histórica de la dictadura de los hermanos Tinoco en Costa Rica y su impacto en la construcción de la democracia nacional.
            </p>
            <button className="cta-button">Descubre más</button>
        </div>
    );
};

export default Hero;
